	o.R.RoleNameRolePermissions = nil
	o.R.Loaded.RoleNameRolePermissions = false

	related, err := o.RoleNameRolePermissions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.RoleNameRole = o
		rel.R.Loaded.RoleNameRole = true
	}

	o.R.RoleNameRolePermissions = related
	o.R.Loaded.RoleNameRolePermissions = true
